import{_ as t,o as r,c as i,ae as a}from"./chunks/framework.DBosx3SP.js";const p=JSON.parse('{"title":"Curve","description":"","frontmatter":{},"headers":[],"relativePath":"rendering/curve.md","filePath":"rendering/curve.md","lastUpdated":1792996843000}'),o={name:"rendering/curve.md"};function n(l,e,s,c,d,u){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="curve" tabindex="-1">Curve <a class="header-anchor" href="#curve" aria-label="Permalink to &quot;Curve&quot;">​</a></h1><p><strong>This doc needs an update</strong> including the numerical stability comparison for various algorithms to solve a third-order polynomial.</p><h2 id="quadratic-bezier-curve" tabindex="-1">Quadratic bezier curve <a class="header-anchor" href="#quadratic-bezier-curve" aria-label="Permalink to &quot;Quadratic bezier curve&quot;">​</a></h2><ol><li>SDF</li><li>Line flattening</li><li>Smaller proxy objects</li></ol><h2 id="cubic-bezier-curve" tabindex="-1">Cubic bezier curve <a class="header-anchor" href="#cubic-bezier-curve" aria-label="Permalink to &quot;Cubic bezier curve&quot;">​</a></h2><p>It is approximated with 2 quadratic bezier curves. (TODO: this is an incomplete method)</p><h2 id="quadratic-bezier-curve-with-border" tabindex="-1">Quadratic bezier curve with border <a class="header-anchor" href="#quadratic-bezier-curve-with-border" aria-label="Permalink to &quot;Quadratic bezier curve with border&quot;">​</a></h2><p>There is no clear solution.<br> The offset curve for a quadratic bezier curve has no simple closed-form equation, and solving it requires an iterative numeric method within a shader.</p><p>TODO: compare methods</p><h2 id="quadratic-bezier-curve-stroke-with-sdf" tabindex="-1">Quadratic Bezier Curve Stroke with SDF <a class="header-anchor" href="#quadratic-bezier-curve-stroke-with-sdf" aria-label="Permalink to &quot;Quadratic Bezier Curve Stroke with SDF&quot;">​</a></h2><ol><li>Run analytic flattening on a curve to get t1, t2, .. tn (<a href="https://raphlinus.github.io/graphics/curves/2019/12/23/flatten-quadbez.html" target="_blank" rel="noreferrer">https://raphlinus.github.io/graphics/curves/2019/12/23/flatten-quadbez.html</a>)</li><li>Subdivision the quadratic bezier curve at partitioning points computed in step 1</li><li>For each split curve, three controlling points define a triangle containing the curve. Draw the triangle using the quadratic bezier curve SDF.</li></ol><h2 id="straight-line-stroke-with-sdf" tabindex="-1">Straight Line Stroke with SDF <a class="header-anchor" href="#straight-line-stroke-with-sdf" aria-label="Permalink to &quot;Straight Line Stroke with SDF&quot;">​</a></h2><ol><li>Draw a quad around the segment</li><li>Use line SDF in Frag Shader</li></ol><h2 id="filled-object" tabindex="-1">Filled Object <a class="header-anchor" href="#filled-object" aria-label="Permalink to &quot;Filled Object&quot;">​</a></h2><ol><li>Computes the winding number for all pixels on GPU.</li><li>Each pixel checks its winding number + the coverage of curves crossing the pixel</li></ol><h2 id="winding-number-on-gpu" tabindex="-1">Winding Number on GPU <a class="header-anchor" href="#winding-number-on-gpu" aria-label="Permalink to &quot;Winding Number on GPU&quot;">​</a></h2><p>For each pixel row,</p><ul><li>An opening curve adds the winding number to all pixels to the right end</li><li>A closing curve subs the winding number to all pixels to the right end<br> So basically it&#39;s prefix-sum calculation (backdrop)</li></ul><h2 id="do-not" tabindex="-1">Do not: <a class="header-anchor" href="#do-not" aria-label="Permalink to &quot;Do not:&quot;">​</a></h2><ul><li>Loop-blinn is slow in triangulation (N^3)</li></ul><h2 id="cubic-bezier-curve-1" tabindex="-1">Cubic Bezier Curve <a class="header-anchor" href="#cubic-bezier-curve-1" aria-label="Permalink to &quot;Cubic Bezier Curve&quot;">​</a></h2><p>Cubic Bezier Curve is required to interpolate a line strip passing through the given N points.<br> Quadratic Bezier cannot do this; quadratic beziers passing through p1, p2, p3 and p2, p3, p4 are not connected.</p><h3 id="rendering-cubic-bezier-curve-with-fill" tabindex="-1">Rendering Cubic Bezier Curve with Fill <a class="header-anchor" href="#rendering-cubic-bezier-curve-with-fill" aria-label="Permalink to &quot;Rendering Cubic Bezier Curve with Fill&quot;">​</a></h3><p>This is easily calculated.</p><h3 id="rendering-cubic-bezier-stroke" tabindex="-1">Rendering Cubic Bezier Stroke <a class="header-anchor" href="#rendering-cubic-bezier-stroke" aria-label="Permalink to &quot;Rendering Cubic Bezier Stroke&quot;">​</a></h3><p>This requires an approximation or numerical solution.</p><ul><li>The offset curve of a cubic bezier curve is 10th degree polynomial</li><li>There is no closed-form SDF.</li></ul><h3 id="ai-surveys" tabindex="-1">AI Surveys <a class="header-anchor" href="#ai-surveys" aria-label="Permalink to &quot;AI Surveys&quot;">​</a></h3><p>Approximations:</p><ul><li>SDF approx (weasel, conformal maps): <a href="https://www.shadertoy.com/view/lcyBz3" target="_blank" rel="noreferrer">https://www.shadertoy.com/view/lcyBz3</a></li><li>SDF approx (NinjaKoala root isolate) : <a href="https://www.shadertoy.com/view/4sKyzW" target="_blank" rel="noreferrer">https://www.shadertoy.com/view/4sKyzW</a></li><li>SDF approx (NinjaKoala, newton): <a href="https://www.shadertoy.com/view/3lsSzS" target="_blank" rel="noreferrer">https://www.shadertoy.com/view/3lsSzS</a> - some distortions seen at some areas</li><li>2D newton method described in loop-blinn and implemented in pathfinder</li><li><a href="https://gist.github.com/mbostock/8027637" target="_blank" rel="noreferrer">https://gist.github.com/mbostock/8027637</a></li><li><a href="https://gist.github.com/mbostock/8027835" target="_blank" rel="noreferrer">https://gist.github.com/mbostock/8027835</a></li><li>Improved Algebraic Algorithm On Point Projection For Bezier Curves, by Xiao-Diao Chen, Yin Zhou, Zhenyu Shu, Hua Su, and Jean-Claude Paul. <ul><li>In short, &#39;IAM&#39; - 0.001ms (paper) ~ 0.01ms (curve) for 200 points</li><li>Sturm + root isolates, improvement over newton</li><li>Article: <a href="https://computingandrecording.wordpress.com/2017/03/20/closest-point-to-a-cubic-spline/" target="_blank" rel="noreferrer">https://computingandrecording.wordpress.com/2017/03/20/closest-point-to-a-cubic-spline/</a></li><li>Code (slower than paper): <a href="https://github.com/nrtaylor/CubicSplineClosestPoint" target="_blank" rel="noreferrer">https://github.com/nrtaylor/CubicSplineClosestPoint</a></li></ul></li><li>&quot;you can use any method that you would like. It is only a degree-5 polynomial. I have tried strum sequences, VCA (Vincent-Collins-Akritas), and Isolator Polynomials. Finally I opted to use isolator polynomials for its simplicity and performance.&quot;</li></ul><p>Reference:</p><ul><li><p><a href="https://stackoverflow.com/questions/2742610/closest-point-on-a-cubic-bezier-curve/" target="_blank" rel="noreferrer">https://stackoverflow.com/questions/2742610/closest-point-on-a-cubic-bezier-curve/</a></p></li><li><p><a href="https://gist.github.com/mbostock/8027637" target="_blank" rel="noreferrer">https://gist.github.com/mbostock/8027637</a></p><table tabindex="0"><thead><tr><th>Method</th><th>Accuracy</th><th>Shader suitability</th><th>Main risks</th></tr></thead><tbody><tr><td>Shadertoy SDF approximation (lcyBz3)</td><td>Approximate</td><td>High</td><td>Not exact distance, artifacts near high curvature/cusps</td></tr><tr><td>2D Newton (Loop-Blinn-style projection / Pathfinder-style iterative)</td><td>High when converged</td><td>Medium-High</td><td>Can converge to wrong local minimum; needs seed + safeguards</td></tr><tr><td>IAM / Chen et al. (Sturm, VCA, isolator-polynomial family)</td><td>Very high / near-global</td><td>Low-Medium (fragment), Medium (compute)</td><td>Branchy control flow, many edge cases, precision sensitivity</td></tr><tr><td>Bostock 8027637 (scan + binary refine)</td><td>Approximate</td><td>High</td><td>Misses true min if coarse scan too sparse</td></tr><tr><td>Bostock 8027835 (sample + Voronoi)</td><td>Approximate</td><td>High at runtime (with preprocess)</td><td>Precompute/storage cost; sample-density error</td></tr><tr><td>ComputingAndRecording + CubicSplineClosestPoint (Sturm+bisection, SIMD CPU)</td><td>Very high</td><td>Low in fragment shader</td><td>Designed for CPU SIMD; shader divergence/precision pain</td></tr><tr><td>StackOverflow &quot;solve quintic roots of D&#39;(t)&quot; baseline</td><td>Exact in principle</td><td>Medium</td><td>Root solver quality determines robustness/perf</td></tr></tbody></table></li></ul>',32)])])}const b=t(o,[["render",n]]);export{p as __pageData,b as default};
